-- Disposable localhost only; synthetic records and transaction rollback.
BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SELECT extensions.plan(33);
SELECT extensions.ok(NOT has_table_privilege('service_role','public.pelecard_live_attempts','SELECT,INSERT,UPDATE,DELETE'),'private attempts');
SELECT extensions.ok(NOT has_function_privilege('authenticated','public.reserve_pelecard_live_order(uuid,uuid,integer,uuid)','EXECUTE'),'browser cannot reserve');
SELECT extensions.ok(NOT has_function_privilege('service_role','public.claim_pelecard_live_init(uuid)','EXECUTE'),'service cannot dispatch');
SELECT extensions.ok(NOT has_function_privilege('pelecard_controlled_live_adapter','public.finalize_pelecard_live(uuid,text,text,text,numeric,text)','EXECUTE'),'adapter cannot finalize');
INSERT INTO auth.users(id,email) VALUES('78000000-0000-4000-8000-000000000001','permanent-admin@example.test');
SELECT set_config('request.jwt.claims','{"role":"service_role"}',true);
UPDATE public.profiles SET role='admin' WHERE id='78000000-0000-4000-8000-000000000001';
INSERT INTO public.orders(id,order_number,client_name,client_phone,activity_date,num_participants,total_price) VALUES('78000000-0000-4000-8000-000000000002','LOCAL-LIFECYCLE','Synthetic','0500000000',CURRENT_DATE,1,47.25);
INSERT INTO public.accounting_events(id,source_type,source_id,purpose,accounting_provider) VALUES('78000000-0000-4000-8000-000000000004','order','78000000-0000-4000-8000-000000000002','payment_success','rivhit');
SELECT extensions.throws_ok($$SELECT public.reserve_pelecard_live_order('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000099',4725)$$,'42501','payment_admin_required','admin actor required');
SELECT extensions.throws_ok($$SELECT public.reserve_pelecard_live_order('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001',3500)$$,'23514','order_amount_mismatch','stale amount rejected');
SELECT set_config('test.live_payment',(public.reserve_pelecard_live_order('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001',4725)->>'id'),true);
SELECT extensions.ok(NOT (public.reserve_pelecard_live_order('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001',4725)->>'created')::boolean,'retry returns same attempt');
SELECT extensions.throws_ok($$SELECT public.reserve_pelecard_live_order('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001',4725,'78000000-0000-4000-8000-000000000099')$$,'23514','stale_payment_attempt','stale predecessor blocked');
SELECT extensions.is((SELECT amount_minor FROM public.claim_pelecard_live_init(current_setting('test.live_payment')::uuid)),4725,'stored amount dispatched');
SELECT extensions.is((SELECT count(*) FROM public.claim_pelecard_live_init(current_setting('test.live_payment')::uuid)),0::bigint,'no dispatch retry');
SELECT extensions.lives_ok($$SELECT public.persist_pelecard_live_adapter_session(current_setting('test.live_payment')::uuid,'78000000-0000-4000-8000-000000000003','synthetic-key','https://gateway20.pelecard.biz/PaymentGW?transactionId=78000000-0000-4000-8000-000000000003')$$,'persist session');
SELECT extensions.throws_ok($$SELECT public.persist_pelecard_live_adapter_session(current_setting('test.live_payment')::uuid,'78000000-0000-4000-8000-000000000003','changed-key','https://gateway20.pelecard.biz/PaymentGW?transactionId=78000000-0000-4000-8000-000000000003')$$,'23514','live_session_mismatch','private correlation immutable');
SELECT extensions.ok(position('synthetic-key' in public.get_pelecard_order_payment_ui('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001')::text)=0,'UI excludes confirmation key');
SELECT public.observe_pelecard_live_attempt(current_setting('test.live_payment')::uuid,'expired','510',NULL,true);
SELECT public.observe_pelecard_live_attempt(current_setting('test.live_payment')::uuid,'usable','510',NULL,true);
SELECT extensions.is((SELECT hosted_state FROM public.pelecard_live_attempts WHERE payment_id=current_setting('test.live_payment')::uuid),'expired','stale observation cannot revive expired session');
SELECT extensions.throws_ok($$INSERT INTO public.sales(items,total,method,sale_date,order_id) VALUES('[]',47.25,'מזומן',CURRENT_DATE,'78000000-0000-4000-8000-000000000002')$$,'23514','live_order_sale_reserved','manual sale cannot overlap active attempt');
SELECT extensions.throws_ok($$INSERT INTO public.sales(items,total,method,sale_date,linked_order_info) VALUES('[]',47.25,'מזומן',CURRENT_DATE,'{"order_number":"LOCAL-LIFECYCLE"}')$$,'23514','live_order_sale_reserved','alias cannot bypass active ownership');
INSERT INTO public.sales(id,items,total,method,sale_date) VALUES('78000000-0000-4000-8000-000000000007','[]',47.25,'מזומן',CURRENT_DATE);
SELECT extensions.throws_ok($$UPDATE public.sales SET linked_order_info='{"order_number":"LOCAL-LIFECYCLE"}' WHERE id='78000000-0000-4000-8000-000000000007'$$,'23514','live_order_sale_reserved','update cannot alias an existing sale into active order');
SELECT extensions.is((SELECT status FROM public.payment_transactions WHERE id=current_setting('test.live_payment')::uuid),'pending_provider','510 expiry never fails payment');
SELECT extensions.ok(NOT (public.get_pelecard_order_payment_ui('78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001')->>'can_replace')::boolean,'510 cannot release ownership');
SELECT extensions.throws_ok($$SELECT public.reserve_pelecard_payment(gen_random_uuid(),'78000000-0000-4000-8000-000000000002','78000000-0000-4000-8000-000000000001','bypass',47.25,'ILS','{}')$$,'23514','live_attempt_already_reserved','legacy reservation cannot bypass');
SELECT extensions.throws_ok($$SELECT public.fail_pelecard_payment(current_setting('test.live_payment')::uuid,'510','browser_failure')$$,'23514','live_financial_transition_forbidden','browser failure cannot terminate');
SELECT extensions.throws_ok($$DELETE FROM public.pelecard_live_attempts WHERE payment_id=current_setting('test.live_payment')::uuid$$,'23514','live_identity_immutable','attempt cannot delete');
SELECT extensions.throws_ok($$UPDATE public.pelecard_live_audit SET event_type='observed' WHERE payment_id=current_setting('test.live_payment')::uuid$$,'23514','live_audit_append_only','audit append only');
SELECT extensions.throws_ok($$SELECT public.finalize_pelecard_live(current_setting('test.live_payment')::uuid,'78000000-0000-4000-8000-000000000003','approval','000',35,'ILS')$$,'23514','live_verification_mismatch','wrong amount rejected');
SELECT public.observe_pelecard_live_attempt(current_setting('test.live_payment')::uuid,'expired','000','000',true);
SELECT extensions.lives_ok($$SELECT public.finalize_pelecard_live(current_setting('test.live_payment')::uuid,'78000000-0000-4000-8000-000000000003','approval','000',47.25,'ILS')$$,'authoritative approval finalizes');
SELECT extensions.lives_ok($$SELECT public.finalize_pelecard_live(current_setting('test.live_payment')::uuid,'78000000-0000-4000-8000-000000000003','approval','000',47.25,'ILS')$$,'finalize retry idempotent');
SELECT extensions.is((SELECT count(*) FROM public.sales WHERE order_id='78000000-0000-4000-8000-000000000002'),1::bigint,'single sale');
SELECT extensions.is((SELECT count(*) FROM public.accounting_events WHERE source_id=current_setting('test.live_payment')),0::bigint,'no accounting events');
SELECT extensions.ok(public.is_pelecard_controlled_live_accounting_held((SELECT sale_id::text FROM public.payment_transactions WHERE id=current_setting('test.live_payment')::uuid)),'sale hold survives success');
SELECT extensions.throws_ok($$UPDATE public.sales SET order_id=NULL,linked_order_info=NULL WHERE payment_transaction_id=current_setting('test.live_payment')::uuid$$,'23514','live_order_sale_reserved','verified sale cannot be detached from held order');
SELECT extensions.throws_ok($$SELECT * FROM public.claim_accounting_event('78000000-0000-4000-8000-000000000004','future-worker',300,true)$$,'23514','controlled_live_accounting_hold','stale accounting event remains unclaimable');
INSERT INTO public.orders(id,order_number,client_name,client_phone,activity_date,num_participants,total_price) VALUES('78000000-0000-4000-8000-000000000005','LOCAL-UNTRACKED','Synthetic','0500000000',CURRENT_DATE,1,47.25);
SELECT public.reserve_pelecard_order_payment('78000000-0000-4000-8000-000000000006','78000000-0000-4000-8000-000000000005','78000000-0000-4000-8000-000000000001','untracked',47.25,'ILS','{}');
SELECT public.fail_pelecard_payment('78000000-0000-4000-8000-000000000006','510','legacy-failure');
SELECT extensions.throws_ok($$SELECT public.reserve_pelecard_live_order('78000000-0000-4000-8000-000000000005','78000000-0000-4000-8000-000000000001',4725)$$,'23514','order_payment_in_progress','even legacy failed payment blocks unproven replacement');
SELECT extensions.ok(NOT (SELECT enabled FROM public.pelecard_controlled_live_control),'legacy gate remains disabled');
SELECT * FROM extensions.finish();
ROLLBACK;
